"""Regression and contract tests for the explicit CPU double ILU v2 policy."""
from types import SimpleNamespace

import numpy as np
import pytest
from scipy import sparse
from scipy.sparse import linalg as sla

from emsolver.contracts import resolve_config
from emsolver.numerics import algorithm_plan, capabilities, estimate_resources
from emsolver.numerics.preconditioning import BudgetedILU


def breakdown_matrix():
    # Independent synthetic, deletion-minimal 33-row counterexample. The
    # coefficients are frozen rather than regenerated by SciPy random APIs.
    pairs = [(0, 3, 1.0000000000000002e-10), (0, 11, -1.0000000000000001e-07), (0, 12, -1e-09), (0, 17, 0.001), (1, 4, -1.0000000000000002e-14), (1, 6, 1e-17), (1, 14, 1.0000000000000002e-12), (1, 15, 1e-16), (1, 16, 1.0000000000000002e-12), (2, 10, 1e-18), (2, 20, -0.0001), (2, 21, 1e-05), (2, 26, 1e-09), (2, 32, -1.0000000000000002e-13), (3, 9, -1.0000000000000002e-13), (3, 14, 1e-18), (3, 25, 1.0000000000000002e-10), (4, 5, -1e-09), (4, 15, 0.1), (4, 21, -0.01), (4, 30, 1.0000000000000002e-10), (5, 9, 1.0000000000000001e-07), (5, 26, -1.0000000000000001e-11), (6, 20, -1e-05), (6, 31, -1.0000000000000002e-14), (6, 32, -1.0000000000000002e-14), (7, 14, -1.0000000000000002e-12), (7, 23, 1.0000000000000001e-11), (8, 22, 1e-16), (8, 25, -1.0000000000000001e-07), (9, 13, 1.0000000000000002e-06), (9, 16, 1e-08), (9, 21, -1e-05), (9, 22, 1e-08), (9, 29, -1.0000000000000002e-06), (10, 24, -1e-18), (10, 25, 1e-17), (11, 13, -0.1), (11, 15, -1.0), (11, 17, 0.0001), (11, 21, -1e-15), (11, 25, 0.001), (11, 28, -1.0000000000000002e-12), (11, 32, 1e-17), (12, 17, -1e-18), (12, 24, -0.001), (12, 31, 1e-09), (13, 17, 1.0000000000000002e-06), (13, 18, -1e-05), (13, 19, -1.0000000000000001e-11), (13, 21, 1e-17), (13, 27, -1e-08), (13, 32, -0.001), (14, 22, 0.009999999999999998), (14, 23, -1e-08), (14, 28, -1.0), (15, 23, -1e-18), (15, 27, 1e-09), (16, 18, -1e-05), (16, 24, 1.0000000000000002e-06), (16, 25, 1e-16), (16, 30, 1.0000000000000002e-12), (17, 29, 1.0000000000000001e-11), (18, 23, -1.0000000000000002e-13), (18, 27, 1e-16), (19, 32, 1e-18), (20, 24, -1.0000000000000002e-13), (20, 27, 1.0000000000000002e-06), (20, 29, -1e-16), (21, 28, 0.0001), (22, 30, 1e-09), (23, 26, 1e-08), (23, 27, 0.1), (23, 28, 1.0000000000000002e-10), (23, 31, 1e-15), (24, 30, -0.0001), (25, 30, 1.0000000000000002e-10), (26, 32, -1e-08), (27, 32, -1.0000000000000001e-11), (28, 32, -1.0000000000000001e-11)]
    rows, cols, values = map(np.asarray, zip(*pairs))
    a = sparse.coo_matrix((values, (rows, cols)), shape=(33, 33)).tocsr()
    a = a+a.T
    a.data /= np.max(np.abs(a.data))
    return a


def config(profile="ilu_equilibrated_compensated_v2", **resources):
    return resolve_config({'target': {'k': 2, 'sigma': 0.},
        'solver': {'method': 'jacobi_davidson', 'transform': 'precond', 'subspace_max': 24,
                   'linear': {'method': 'gmres', 'preconditioner': profile}},
        'resources': {'threads': 1, **resources}})


class Runtime:
    def __init__(self, callback=None):
        self.process = SimpleNamespace(memory_info=lambda: SimpleNamespace(rss=0))
        self.callback = callback
        self.events = []
    def check(self):
        if self.callback: self.callback()
    def emit(self, stage, event, **fields):
        self.check(); self.events.append((event, fields))


def build(a, profile="ilu_equilibrated_compensated_v2", runtime=None, **resources):
    counters = {'factorizations': 0, 'preconditioner_applications': 0}
    ilu = BudgetedILU.build(a, 0., config(profile, **resources), runtime or Runtime(), counters)
    return ilu, counters


def test_v2_solves_same_original_correction_when_v1_factor_breaks_down():
    a = breakdown_matrix()
    with pytest.raises(RuntimeError, match='PRECONDITIONER_FAILED'):
        build(a, 'ilu_budgeted_v1')
    ilu, counters = build(a)
    rng = np.random.default_rng(5)
    q = np.linalg.qr(rng.standard_normal((33, 2)))[0]
    inverse = ilu.constrained_inverse(q)
    theta = .03
    def project(v): return v-q@(q.T@v)
    def operation(v):
        p = project(v)
        return project(a@p-theta*p)+q@(q.T@v)
    rhs = project(rng.standard_normal(33))
    operator = sla.LinearOperator(a.shape, matvec=operation, dtype=np.float64)
    preconditioner = sla.LinearOperator(a.shape, matvec=inverse.apply, dtype=np.float64)
    result, info = sla.gmres(operator, rhs, M=preconditioner, rtol=1e-8, atol=0., restart=33, maxiter=200)
    assert info == 0
    assert np.linalg.norm(operation(result)-rhs)/np.linalg.norm(rhs) <= 1e-8
    # Small independent dense oracle only in this synthetic regression.
    reference = np.linalg.solve(np.column_stack([operation(v) for v in np.eye(33)]), rhs)
    np.testing.assert_allclose(result, reference, rtol=1e-5, atol=1e-5)
    assert counters['factorizations'] == 1
    assert counters['preconditioner_factorizations'] == 1


@pytest.mark.parametrize('complex_values', [False, True])
@pytest.mark.parametrize('scale', [1., 1e-300, 1e300])
def test_v2_scaling_and_constrained_inverse_preserve_original_coordinates(complex_values, scale):
    diagonal = np.array([-3., -2., -1., 1., 2., 3.])
    off = np.full(5, .05, dtype=complex if complex_values else float)
    if complex_values: off += .03j
    a = sparse.diags([off.conjugate(), diagonal, off], [-1,0,1], format='csr')*scale
    original = a.copy()
    ilu, counters = build(a)
    q = np.eye(6, dtype=a.dtype)[:,[0,3]]
    constrained = ilu.constrained_inverse(q)
    rhs = np.arange(1.,7.).astype(a.dtype)
    if complex_values: rhs += .1j*np.arange(6.)
    shifted = a-sparse.eye(6)*counters['preconditioner_work_shift_scaled']
    np.testing.assert_allclose(shifted@ilu.apply(rhs), rhs, rtol=1e-12, atol=1e-12)
    p = np.eye(6)-q@q.conjugate().T
    operator = p@shifted.toarray()@p+q@q.conjugate().T
    solution = constrained.apply(rhs)
    np.testing.assert_allclose(operator@solution, rhs, rtol=1e-12, atol=1e-12)
    np.testing.assert_allclose(constrained.apply(2*rhs), 2*solution, rtol=1e-12)
    assert (original != a).nnz == 0
    assert solution.dtype == a.dtype
    assert counters['preconditioner_equilibration_passes'] == 4
    assert counters['preconditioner_factorizations'] == 1
    assert counters['preconditioner_constraint_builds'] == 1
    assert counters['preconditioner_constraint_setup_factor_solves'] == 2
    assert counters['preconditioner_constraint_solves'] == 2
    assert counters['preconditioner_factor_solves'] == 5
    assert counters['preconditioner_scaling_applications'] == 10


def test_v2_capability_policy_and_resource_model_are_explicit_and_do_not_mutate_v1():
    v2 = algorithm_plan(config())['linear_solver']['preconditioner_policy']
    assert v2['id'] == 'ilu_equilibrated_compensated_v2'
    assert v2['equilibration_sweeps'] == 4 and v2['diagonal_row_l1_floor'] == .01
    assert v2['retry_or_profile_fallback'] is False
    v2['scaling_step_clip'][0] = 42
    assert algorithm_plan(config())['linear_solver']['preconditioner_policy']['scaling_step_clip'][0] == 1e-100
    assert 'ilu_equilibrated_compensated_v2' in capabilities()['jacobi_davidson']['preconditioners']
    assert resolve_config({})['solver']['linear']['preconditioner'] == 'auto_budgeted'
    a = breakdown_matrix()
    estimate = estimate_resources(a, config())
    old = estimate_resources(a, config('ilu_budgeted_v1'))
    assert estimate['minimum_memory_bytes'] > old['minimum_memory_bytes']
    for key in ('ilu_v2_equilibration_sparse_scratch_bytes', 'ilu_v2_scaling_diagonal_vectors_bytes',
                'ilu_v2_constraint_vectors_bytes', 'ilu_v2_constraint_small_workspace_bytes'):
        assert estimate['components'][key] > 0
        assert key not in old['components']
    assert estimate['factorization_fill_in']['bounded'] is False
    assert estimate['requires_runtime_process_tree_guard'] is True


@pytest.mark.parametrize('bad', [np.ones((33,2)), np.full((33,2),np.nan), np.full((33,2),'bad')])
def test_v2_rejects_invalid_selected_blocks_with_stable_failure(bad):
    ilu, _ = build(breakdown_matrix())
    with pytest.raises(RuntimeError, match='PRECONDITIONER_FAILED'):
        ilu.constrained_inverse(bad)


def test_v2_rejects_singular_schur_without_switching_policy(monkeypatch):
    ilu, counters = build(breakdown_matrix())
    q = np.eye(33)[:,:1]
    def inverse(v):
        result = v.copy(); result[0], result[1] = v[1], v[0]
        return result
    monkeypatch.setattr(ilu, 'apply', inverse)
    with pytest.raises(RuntimeError, match='singular_or_ill_conditioned_schur'):
        ilu.constrained_inverse(q)
    assert counters['preconditioner_factorizations'] == 1
    assert counters['preconditioner_constraint_builds'] == 0


def test_v2_budget_rejects_before_sparse_setup_and_constraint_copy(monkeypatch):
    a = breakdown_matrix()
    original = sparse.csr_matrix.tocsr
    def forbidden(*args, **kwargs):
        if kwargs.get('copy', False): pytest.fail('unsafe sparse copy reached')
        return original(*args, **kwargs)
    monkeypatch.setattr(sparse.csr_matrix, 'tocsr', forbidden)
    with pytest.raises(RuntimeError, match='RESOURCE_EXHAUSTED'):
        build(a, memory_limit_gib=1e-6)
    monkeypatch.setattr(sparse.csr_matrix, 'tocsr', original)
    ilu, _ = build(a)
    ilu.budget_bytes = 1
    q = np.eye(33)[:,:2]
    with pytest.raises(RuntimeError, match='RESOURCE_EXHAUSTED.*constraint'):
        ilu.constrained_inverse(q)


def test_v2_cancellation_propagates_during_constraint_setup_and_apply():
    state = {'stop':False}
    def check():
        if state['stop']: raise InterruptedError('CANCELLED: controlled v2 boundary')
    runtime = Runtime(check)
    ilu, _ = build(breakdown_matrix(), runtime=runtime)
    q = np.eye(33)[:,:2]
    state['stop'] = True
    with pytest.raises(InterruptedError, match='CANCELLED'):
        ilu.constrained_inverse(q)
    state['stop'] = False
    inverse = ilu.constrained_inverse(q)
    state['stop'] = True
    with pytest.raises(InterruptedError, match='CANCELLED'):
        inverse.apply(np.ones(33))


def test_v2_nonfinite_solve_and_factor_failure_are_explicit_without_retry(monkeypatch):
    from emsolver.numerics import preconditioning
    calls = []
    def fail(*args, **kwargs):
        calls.append(kwargs); raise RuntimeError('Factor is exactly singular')
    monkeypatch.setattr(preconditioning.sla, 'spilu', fail)
    runtime = Runtime()
    with pytest.raises(RuntimeError, match='PRECONDITIONER_FAILED.*singular_pivot'):
        build(breakdown_matrix(), runtime=runtime)
    assert len(calls) == 1
    assert calls[0]['fill_factor'] == 2. and calls[0]['drop_tol'] == 1e-3
    assert any(event=='preconditioner_failed' for event,_ in runtime.events)
    factor = SimpleNamespace(nnz=100, solve=lambda rhs: np.full_like(rhs,np.nan))
    monkeypatch.setattr(preconditioning.sla, 'spilu', lambda *args,**kwargs: factor)
    ilu, _ = build(breakdown_matrix())
    with pytest.raises(RuntimeError, match='PRECONDITIONER_FAILED.*nonfinite'):
        ilu.apply(np.ones(33))


def test_v2_cancels_between_equilibration_passes_before_factorization(monkeypatch):
    from emsolver.numerics import preconditioning
    counters = {'factorizations': 0, 'preconditioner_applications': 0}
    def check():
        if counters.get('preconditioner_equilibration_passes', 0) == 2:
            raise InterruptedError('CANCELLED: after second equilibration pass')
    def forbidden(*args, **kwargs): pytest.fail('cancelled setup reached native factorization')
    monkeypatch.setattr(preconditioning.sla, 'spilu', forbidden)
    a = breakdown_matrix(); original = a.copy()
    with pytest.raises(InterruptedError, match='CANCELLED'):
        BudgetedILU.build(a, 0., config(), Runtime(check), counters)
    assert counters['preconditioner_equilibration_passes'] == 2
    assert (a != original).nnz == 0


def test_v2_native_allocation_failure_keeps_resource_error_and_single_attempt(monkeypatch):
    from emsolver.numerics import preconditioning
    attempts = []
    def fail(*args, **kwargs):
        attempts.append(1)
        raise MemoryError('controlled native allocation failure')
    monkeypatch.setattr(preconditioning.sla, 'spilu', fail)
    with pytest.raises(RuntimeError, match='RESOURCE_EXHAUSTED.*factorization'):
        build(breakdown_matrix())
    assert len(attempts) == 1


def test_v2_does_not_export_factor_copies_or_dense_original(monkeypatch):
    from emsolver.numerics import preconditioning
    original = preconditioning.sla.spilu
    class InternalFactor:
        def __init__(self, factor): self._factor = factor
        @property
        def nnz(self): return self._factor.nnz
        @property
        def L(self): pytest.fail('L export would add unbudgeted factor copies')
        @property
        def U(self): pytest.fail('U export would add unbudgeted factor copies')
        def solve(self, rhs): return self._factor.solve(rhs)
    monkeypatch.setattr(preconditioning.sla, 'spilu', lambda *args, **kwargs: InternalFactor(original(*args, **kwargs)))
    original_toarray = sparse.csr_matrix.toarray
    def bounded_toarray(matrix, *args, **kwargs):
        if min(matrix.shape) > 1: pytest.fail('full original matrix must remain sparse')
        return original_toarray(matrix, *args, **kwargs)
    monkeypatch.setattr(sparse.csr_matrix, 'toarray', bounded_toarray)
    ilu, counters = build(breakdown_matrix())
    constrained = ilu.constrained_inverse(np.eye(33)[:, :2])
    assert np.isfinite(constrained.apply(np.ones(33))).all()
    assert counters['preconditioner_factor_nnz'] > 0


@pytest.mark.parametrize('patch,code', [({'precision':'mixed_float32'},'UNSUPPORTED_PRECISION')])
def test_v2_rejects_unsupported_precision(patch,code):
    cfg = config(); cfg['solver']['linear'].update(patch)
    with pytest.raises(ValueError,match=code): algorithm_plan(cfg)
    cfg = config(); cfg['resources']['device'] = 'gpu'
    with pytest.raises(ValueError,match='UNSUPPORTED_PRECONDITIONER'): algorithm_plan(cfg)
